WITH scored AS (SELECT *, FIRST_VALUE(status) IGNORE NULLS OVER (PARTITION BY status, customer_id ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_status, PERCENT_RANK() OVER (ORDER BY balance NULLS LAST) AS balance_percent_rank, COUNT(balance) OVER (PARTITION BY customer_id) AS customer_id_count_balance FROM accounts) SELECT id, account_type, balance, first_known_status, balance_percent_rank, customer_id_count_balance FROM scored ORDER BY account_type
